TLM.f("Tempora/Pasc0-2",{"officium":"Die III infra octavam Paschæ","rule":["ex Pasc0-0;","Credo","Sequentia"],"ruleInherited":["Sequentia","Credo","Prefatio=Pasch"],"fallback":"Tempora/Pasc0-0","sections":{"Introitus":[{"k":"ref","la":"Eccli 15:3-4"},{"k":"text","la":"Aqua sapiéntiæ potávit eos, allelúja: firmábitur in illis et non flectétur, allelúja: et exaltábit eos in ætérnum, allelúja, allelúja."},{"k":"ref","la":"Ps 104: 1"},{"k":"text","la":"Confitémini Dómino et invocáte nomen ejus: annuntiáte inter gentes ópera ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Aqua sapiéntiæ potávit eos, allelúja: firmábitur in illis et non flectétur, allelúja: et exaltábit eos in ætérnum, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui Ecclésiam tuam novo semper fœtu multíplicas: concéde fámulis tuis; ut sacraméntum vivéndo téneant, quod fide percepérunt."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Acts 13:16; 13:26-33"},{"k":"text","la":"In diébus illis: Surgens Paulus et manu siléntium índicens, ait: Viri fratres, fílii géneris Abraham, et qui in vobis timent Deum, vobis verbum salútis hujus missum est. Qui enim habitábant Jerúsalem, et príncipes ejus, ignorántes Jesum et voces Prophetárum, quæ per omne sábbatum legúntur, judicántes implevérunt: et nullam causam mortis inveniéntes in eo, petiérunt a Piláto, ut interfícerent eum. Cumque consummássent ómnia, quæ de eo scripta erant, deponéntes eum de ligno, posuérunt eum in monuménto. Deus vero suscitávit eum a mórtuis tértia die: qui visus est per dies multos his, qui simul ascénderant cum eo de Galilǽa in Jerúsalem, qui usque nunc sunt testes ejus ad plebem. Et nos vobis annuntiámus eam, quæ ad patres nostros repromíssio facta est: quóniam hanc Deus adimplévit fíliis nostris, resúscitans Jesum Christum, Dóminum nostrum."}],"Graduale":[{"k":"ref","la":"Ps 117:24;106:2"},{"k":"text","la":"Hæc dies, quam fecit Dóminus: exsultémus et lætémur in ea."},{"k":"ref","la":"Ps 106:2"},{"k":"text","la":"Dicant nunc, qui redémpti sunt a Dómino: quos redémit de manu inimíci, et de regiónibus congregávit eos.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Surrexit Dóminus de sepúlcro, qui pro nobis pepéndit in ligno.","mark":"V"}],"Sequentia":[{"k":"text","la":"Víctimæ pascháli laudes ímmolent Christiáni."},{"k":"text","la":"Agnus rédemit oves: Christus ínnocens Patri reconciliávit peccatóres."},{"k":"text","la":"Mors et vita duéllo conflixére mirándo: dux vitæ mórtuus regnat vivus."},{"k":"text","la":"Dic nobis, María, quid vidísti in via?"},{"k":"text","la":"Sepúlcrum Christi vivéntis et glóriam vidi resurgéntis."},{"k":"text","la":"Angélicos testes, sudárium et vestes."},{"k":"text","la":"Surréxit Christus, spes mea: præcédet vos in Galilǽam."},{"k":"text","la":"Scimus Christum surrexísse a mórtuis vere: tu nobis, victor Rex, miserére. Amen. Allelúja."},{"k":"rubric","la":"Sequentia dicitur usque ad Sabbatum in Albis inclusive."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc. 24, 36-47"},{"k":"text","la":"In illo témpore: Stetit Jesus in médio discipulórum suórum et dicit eis: Pax vobis: ego sum, nolíte timére. Conturbáti vero et contérriti, existimábant se spíritum vidére. Et dixit eis: Quid turbáti estis, et cogitatiónes ascéndunt in corda vestra? Vidéte manus meas et pedes, quia ego ipse sum: palpáte et vidéte: quia spíritus carnem et ossa non habet, sicut me vidétis habére. Et cum hoc dixísset, osténdit eis manus et pedes. Adhuc autem illis non credéntibus et mirántibus præ gáudio, dixit: Habétis hic aliquid, quod manducétur? At illi obtulérunt ei partem piscis assi et favum mellis. Et cum manducásset coram eis, sumens relíquias, dedit eis. Et dixit ad eos: Hæc sunt verba, quæ locútus sum ad vos, cum adhuc essem vobíscum, quóniam necésse est impléri ómnia, quæ scripta sunt in lege Móysi et Prophétis et Psalmis de me. Tunc apéruit illis sensum, ut intellégerent Scriptúras. Et dixit eis: Quóniam sic scriptum est, et sic oportébat Christum pati, et resúrgere a mórtuis tértia die: et prædicári in nómine ejus pœniténtiam, et remissiónem peccatórum in omnes gentes."}],"Offertorium":[{"k":"ref","la":"Ps. 17:14; 17:16"},{"k":"text","la":"Intónuit de cœlo Dóminus, et Altíssimus dedit vocem suam: et apparuérunt fontes aquárum, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, fidélium preces cum oblatiónibus hostiárum: ut, per hæc piæ devotiónis offícia, ad cœléstem glóriam transeámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Col 3:1-2"},{"k":"text","la":"Si consurrexístis cum Christo, quæ sursum sunt quǽrite, ubi Christus est in déxtera Dei sedens, allelúja: quæ sursum sunt sápite, allelúja."}],"Postcommunio":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut paschális percéptio sacraménti, contínua in nostris méntibus persevéret."},{"k":"macro","name":"Per Dominum"}]},"hr":{"9e204d9512691bc1":{"t":"Sir 15, 3 i 4, Ps 104, 1\n(Sir 15, 3 i 4) Vodom ih je mudrosti napojio, aleluja! Ojačat će ih da se ne slome, <i>aleluja</i>!\nUzvisit će ih zauvijek, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 104, 1) Slavite Gospodina i zazivajte ime njegovo, naviještajte među narodima djela njegova.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 3 i 4) Vodom ih je mudrosti napojio, aleluja! Ojačat će ih da se ne slome, <i>aleluja</i>!\nUzvisit će ih zauvijek, <i>aleluja</i>, <i>aleluja</i>.","v":"∅ → et; ∅ → et","kn":"(Crkv. 15, 3, 4). Vodom ih je mudrosti napojio, aleluja; -ojačat će ih, da se ne prignu, aleluja: uzvisit će ih zauvijek, aleluja, aleluja (Ps. 104, 1). Slavite Gospodina i zazivajte ime njegovo, naviještajte među ljudima djela njegova. Slava Ocu . . . Vodom . . .","knRef":"Kniewald 1942, str. 304–305 (snimka 153) (OCR)"},"b5425268178acd36":{"t":"<i>Pomolimo se</i>.\nBože, koji Crkvu svoju umnažaš uvijek novim potomstvom, dopusti da službenici tvoji životom svjedoče tajnu koju su vjerom primili.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji Crkvu svoju umnažaš uvijek novim potomstvom, .dopusti, da službenici Tvoji životom svjedoče tajnu, koju su vjerom primili, PO G. o.","knRef":"Kniewald 1942, str. 304–305 (snimka 153) (OCR)"},"d84e02907f0a9251":{"t":"Dj 13, 16 i 26-33\nČitanje Djela apostolskih: U one dane ustade Pavao i mahnuvši rukom reče: Ljudi, braćo, sinovi roda Abrahamova, i koji se među vama boje Boga! Nama je poslana riječ spasenja ovoga. Jer oni što stanuju u Jeruzalemu i glavari njihovi nisu poznali onoga i osudivši ga ispunili su riječi proroka koji se čitaju svake subote. I premda nisu našli nijedne krivice na njemu koja bi zaslužila smrt, zahtijevali su od Pilata da ga pogubi. I kad su sve svršili što je pisano za njega, skinu ga s križa i polože u grob. Ali Bog ga je oživio od mrtvih. I on se više dana pokazivao onima što siđoše s njime iz Galileje u Jeruzalem koji su sada svjedoci njegovi pred narodom. I mi vam propovijedamo da je Bog ono obećanje, koje je dao ocima našim, ispunio djeci našoj uskrsnuvši Isusa Gospodina našega.","kn":"Čitanje Djela apostolskih (13, 16, 26-33). U onim danima ustade .Pavao i mahnuvšl rukom reče: Ljudi, braćo, sinovi roda Abrahamova, i koji se među vama boje Boga! Nama je poslana riječ spasenja ovoiga. Jer -oni, što stanuju u Jeruzalemu i glavari njihovi nisu poznali ovoga, i osudivši ga, ispunili suriječi proroka, boje se čitaju svake subote; i zo premda iiisu našli nijedne krivice ha njemu, keja bi zaslužila smrt, zahtijevali su od Pilata, da ga pogubi. I kad su sve svršili, što je pisano za njega, skinu ga s križa i polože u grob. Ali' Bog ga je oživio od mrtvih. I on se više dana pokazivao onima', što siđoše , s njime iz Galileje u Jeruzalem, koji su sada svjedoci njegovi pred narodom. I mi. vam propovijedam-o, da je Bog ono obećanje, koje je dao 'Oama našim, ispunio djeci našoj usknsnuvši Isusa, Gospodina našega.","knRef":"Kniewald 1942, str. 304–305 (snimka 153) (OCR)"},"4d4d8306b9086a5c":{"t":"Ps 117, 24, Ps 106, 2\n(Ps 117, 24) Ovo je dan što ga učini Gospodin! Kličimo i radujmo se danas! (Ps 106, 2) Tako neka govore oni koje je otkupio Gospodin, koje je izbavio iz ruke neprijatelja i sakupio iz svih zemalja.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nUskrsnuo je iz groba Gospodin koji je za nas visio na križu.","kn":"(Ps. 117, 24). Ovo je dan, koji nam je pripravio Gospodin^ klićimo i radujmo se (Ps, 106, 2). Tako neka govore oni, koje je otkupio Gospodin, koje je izbavio ' iz ruke neprijatelja, i sakupio iz svih zemalja. Alejuja, , aleluja. Uskrsnuo je iz groba Gospodin, koji je za nas visio na križu.","knRef":"Kniewald 1942, str. 306–307 (snimka 154) (OCR)"},"a670bd50efcad44c":{"t":"Svetoj Žrtvi uskrsnici dajte slavu krštenici!<i>\n</i>\nJanje ovce oslobodi Krist nas grješne preporodi.<i>\n</i>\nSa životom smrt se sasta i čudesna borba nasta: Vođa živih pade tada i živ živcat opet vlada.<i>\n</i>\nMarijo, o reci što je? Što ti oko vidjelo je?<i>\n</i>\nGrob ja vidjeh Krista Boga, svijetlu slavu uskrsloga.<i>\n</i>\nAnđele i platno bijelo u kom bješe sveto tijelo.<i>\n</i>\nUfanje mi uskrslo je Krist, moj Gospod i sve moje! Pred vama će tamo gdje je cvjetna strana Galileje.<i>\n</i>\nZnamo da si doistine uskrsnuo Božji Sine! Pobjedniče, Kralju divan, budi nama milostivan!<i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"254845eb9de7f1c5":{"t":"Lk 24, 36-47\nSlijedi sveto Evanđelje po Luki. U ono vrijeme stade Isus među svoje apostole i reče im: Mir vama. A oni su zastrašeni i poplašeni mislili da vide duha. I reče im: Što se plašite i zašto takve misli ulaze u vaša srca? Pogledajte ruke moje i noge! Ja sam, ja glavom! Opipajte me i uvjerite se jer duh nema mesa i kosti kao što vidite da ja imam. I ovo rekavši pokaza im ruke i noge. Budući da oni još nisu vjerovali od radosti i čudili se, reče im: Imate li ovdje što za jelo? A oni mu dadoše komad pečene ribe i meda u saću. On uze i jede pred njima. I reče im: Ovo su riječi koje vam rekoh dok sam još bio s vama da se ima sve ispuniti što je za mene pisano u zakonu Mojsijevu i u prorocima i u psalmima. Tada im otvori razum da razumiju Pisma i reče im: Tako je pisano: Krist treba da trpi i uskrsne od mrtvih treći dan i da se propovijeda u ime njegovo pokora za oproštenje grijeha svim narodima.","kn":"t Slijedi sv. evanđelje po Luki (24, 36-47). U pno vrijeme stade Isus među svoje apostole i reče im! Mir vama. A oni su zastrašeni i poplašeni mislili, da vide duha. I reče im: Što še plašite, jzašto takve misli (ilaze u vaša srca? Pogledajte ruke moje i noge! ja sam, ja glavnom; opipajte me i uvjerite se, jer duh nema mesa ni kosti, kao što vidite, da ja imam. I ovo rekavši pokaza im ruke i noge. Budući da oni još nisu vjerovali bd radosti l^ čudili se, reče im: Imate li ovdjn što za jelo? A oni mu dadoše komad pečene ribe i meda u saću. On uze i jede iM-ed njima. I reče im: Ovo su riječi, koje vam rekoh, dok sam još bio s vama, da se ima šve ispuniti, što je za mene pisano u zakonu Mojsijevu i u (prorocima i u psalmima. Tada im otvori razum, da razumiju Pisma. I reče im: Tako je pisano: Krist treba da trpi i uskrsne od mrtvih treći dan,^ i cfe se propovijeda u ime njegovo pokora za cproštenje grlj-etia Po svim narodima.","knRef":"Kniewald 1942, str. 306–307 (snimka 154) (OCR)"},"7d383d3ca7290b3e":{"t":"Ps 17, 14 i 16\nS neba je zagrmio Gospodin. Višnji je dao glas svoj i pojaviše se izvori voda, <i>aleluja</i>.","kn":"(Ps: 17, 14, 16). S neba je zagrmio Gospodin. Višnji je dao glas svoj. i pojaviše se izvori voda, aleluja.","knRef":"Kniewald 1942, str. 306–307 (snimka 154) (OCR)"},"0fd2e8f96ba76c4c":{"t":"Sa žrtvenim prinosima primi, Gospodine, i molitve svojih vjernika da po ovoj službi pobožne odanosti prijeđemo u nebesku slavu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo. Gospodine, molitve svoga puka, koji Ti prinosi ove žrtve, da po ovoj službi svete pobožnosti prijeđemo u nebesku slavu, po G. n.. *","knRef":"Kniewald 1942, str. 306–307 (snimka 154) (OCR)"},"687cae1ead8b8c38":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>danas</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"5989f09d404737a3":{"t":"Kol 3, 1-2\nAko ste uskrsli s Kristom, tražite ono što je gore, gdje Krist sjedi s desne strane Božje, <i>aleluja</i>.\nTežite za onim što, je gore, <i>aleluja</i>.","kn":"(Kolos. 3, 1, 2). Ako ste uskrsnuli s Kristom, tražite ono, što je gore, gdje Krist sjedi^ s desne strane Božje, aleluja; težite za o-nim, što je gore, aleluja. .","knRef":"Kniewald 1942, str. 306–307 (snimka 154) (OCR)"},"fc4ba2a42598d994":{"t":"<i>Pomolimo se</i>.\nDopusti, molimo, svemogući Bože, da uskrsne tajne što ih primismo djeluju u nama trajnim učinkom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
